window.F = {
  esc: s => String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])),
  vues: n => n >= 1e6 ? (n / 1e6).toFixed(1).replace(".", ",") + " M" : Math.round(n / 1e3) + " k",
  duree: s => { const h = Math.floor(s / 3600), m = Math.round((s % 3600) / 60); return h ? h + " h " + String(m).padStart(2, "0") : m + " min"; },
  annee: d => d.slice(0, 4),
  img: id => "https://i.ytimg.com/vi/" + id + "/maxresdefault.jpg",
  mini: id => "https://i.ytimg.com/vi/" + id + "/mqdefault.jpg",
  total: l => l.reduce((a, v) => a + v.vues, 0),
  clients: () => [...new Set(V.map(v => v.client))],
  // Lecteur commun : clic sur un élément [data-id] -> vidéo par-dessus la page
  lecteur() {
    const d = document.createElement("div");
    d.style.cssText = "position:fixed;inset:0;background:rgba(0,0,0,.9);display:none;align-items:center;justify-content:center;padding:24px;z-index:99";
    document.body.appendChild(d);
    const fermer = () => { d.style.display = "none"; d.innerHTML = ""; };
    document.addEventListener("click", e => {
      const b = e.target.closest("[data-id]");
      if (b) { d.innerHTML = '<iframe style="width:min(1200px,100%);aspect-ratio:16/9;border:0;border-radius:8px" src="https://www.youtube-nocookie.com/embed/' + b.dataset.id + '?autoplay=1" allow="autoplay; fullscreen; encrypted-media" allowfullscreen></iframe>'; d.style.display = "flex"; }
      else if (e.target === d) fermer();
    });
    document.addEventListener("keydown", e => { if (e.key === "Escape") fermer(); });
  }
};
